function validate([buses, passengers, capacity]) {
  if (buses.length < 1 || buses.length > 100000) return 'buses needs 1 to 10^5 times.';
  if (passengers.length < 1 || passengers.length > 100000) return 'passengers needs 1 to 10^5 times.';
  if (!Number.isInteger(capacity) || capacity < 1 || capacity > 100000) return 'capacity is between 1 and 10^5.';
  for (const list of [buses, passengers]) {
    if (list.some(t => !Number.isInteger(t) || t < 2 || t > 1000000000)) return 'Every time is an integer between 2 and 10^9.';
    if (new Set(list).size !== list.length) return 'Times within buses, and within passengers, must be distinct.';
  }
  return null;
}

