function latestTimeCatchTheBus(buses, passengers, capacity) {
  buses.sort((a, b) => a - b);
  passengers.sort((a, b) => a - b);
  let next = 0;
  let boarded = 0;

  for (const departure of buses) {
    boarded = 0;
    while (boarded < capacity && next < passengers.length && passengers[next] <= departure) {
      next++;
      boarded++;
    }
  }

  let last = next - 1;
  let answer = boarded < capacity ? buses[buses.length - 1] : passengers[last];
  while (last >= 0 && passengers[last] === answer) {
    answer--;
    last--;
  }
  return answer;
}

