function latestTimeCatchTheBus(buses, passengers, capacity) {
  const departures = [...buses].sort((a, b) => a - b);
  const taken = new Set(passengers);
  // You can always arrive later unless a rider arrives one minute later or your bus would leave without you,
  // so the best time is a departure time or one minute before some rider (time 1 is always safe).
  const candidates = new Set([1, ...buses, ...passengers.map(p => p - 1)]);
  let best = 0;
  for (const time of candidates) {
    if (time < 1 || taken.has(time) || time <= best) continue;
    const queue = [...passengers, time].sort((a, b) => a - b);
    let front = 0;
    let rode = false;
    for (const departure of departures) {
      let seats = capacity;
      while (seats > 0 && front < queue.length && queue[front] <= departure) {
        if (queue[front] === time) rode = true;
        front++;
        seats--;
      }
    }
    if (rode) best = time;
  }
  return best;
}

