function generate(rand, size) {
  const pick = (count, low, high) => {
    const values = new Set();
    while (values.size < count) values.add(low + Math.floor(rand() * (high - low + 1)));
    return [...values];
  };
  if (size === 'small') {
    const high = 4 + Math.floor(rand() * 26);
    const n = 1 + Math.floor(rand() * Math.min(4, high - 1));
    const m = 1 + Math.floor(rand() * Math.min(8, high - 1));
    return [pick(n, 2, high), pick(m, 2, high), 1 + Math.floor(rand() * 3)];
  }
  // Dense times make riders collide with the best arrival time; wide times test large values.
  const high = rand() < 0.5 ? 5000 : 1000000000;
  const n = 500 + Math.floor(rand() * 1501);
  const m = 1000 + Math.floor(rand() * 1001);
  return [pick(n, 2, high), pick(m, 2, high), 1 + Math.floor(rand() * 4)];
}
